const PortfolioEngine=function(){let e=null;return{init:async function(){if(e=document.getElementById("portfolio-grid"),e)try{e.innerHTML='\n            <div class="col-span-full flex flex-col items-center justify-center py-20 space-y-4">\n                <div class="w-12 h-12 border-4 border-blue-900 border-t-transparent rounded-full animate-spin"></div>\n                <p class="text-blue-900 font-medium animate-pulse">Loading amazing projects...</p>\n            </div>\n        ';let t=[];if("undefined"!=typeof supabase){const{data:e,error:n}=await supabase.from("student_projects").select("*").order("date",{ascending:!1});!n&&e&&e.length>0&&(t=e)}if(0===t.length){const e=await fetch("assets/data/projects.json");e.ok&&(t=await e.json())}!function(t){if(0===t.length)return void(e.innerHTML='<p class="col-span-full text-center text-gray-500 py-10">No projects found.</p>');e.innerHTML=t.map((e,t)=>{const n=Array(5).fill(0).map((t,n)=>`<i data-lucide="star" class="w-3 h-3 fill-current ${n<(e.rating||5)?"":"text-gray-300"}"></i>`).join(""),r=e.badgeColor||"bg-blue-600/90",o=.1*t;return`\n            \x3c!-- Project Card: ${e.title} --\x3e\n            <div class="bg-white rounded-2xl shadow-xl overflow-hidden group transform transition-all duration-500 hover:-translate-y-4 border border-gray-100" style="animation-delay: ${o}s;">\n                <div class="h-56 overflow-hidden relative">\n                    <div class="absolute top-4 left-4 z-10">\n                        <span class="px-3 py-1 ${r} backdrop-blur-md text-white text-xs font-bold rounded-lg uppercase shadow-lg">\n                            ${e.category}\n                        </span>\n                    </div>\n                    <img src="${e.image}"\n                        alt="${e.title}" \n                        class="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700"\n                        loading="lazy">\n                    <div class="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex items-center justify-center">\n                        <a href="${e.viewUrl||"#"}" class="inline-flex items-center px-6 py-3 bg-white rounded-full text-blue-900 font-bold transform translate-y-4 group-hover:translate-y-0 transition-all duration-300 hover:bg-orange-500 hover:text-white">\n                            ${e.ctaText||"View Project"}\n                        </a>\n                    </div>\n                </div>\n                <div class="p-6">\n                    <h3 class="text-xl font-bold text-blue-900 mb-2">${e.title}</h3>\n                    <div class="flex items-center justify-between mb-4">\n                        <p class="text-sm text-gray-500 font-medium flex items-center">\n                            <i data-lucide="user" class="w-4 h-4 mr-1"></i> ${e.studentName}, Age ${e.studentAge}\n                        </p>\n                        <div class="flex text-yellow-400">\n                            ${n}\n                        </div>\n                    </div>\n                    <p class="text-gray-600 text-sm leading-relaxed line-clamp-2">\n                        ${e.description}\n                    </p>\n                </div>\n            </div>\n            `}).join("")}(t),window.gsap&&window.ScrollTrigger&&gsap.from("#portfolio-grid > div",{opacity:0,y:30,duration:.8,stagger:.1,ease:"power2.out",scrollTrigger:{trigger:"#portfolio-grid",start:"top 80%"}}),window.lucide&&window.lucide.createIcons()}catch(t){console.error("[STEMulus] Portfolio Engine Error:",t),e.innerHTML='<p class="col-span-full text-center text-gray-500 py-10">Unable to load projects. Please try again later.</p>'}}}}();"loading"===document.readyState?document.addEventListener("DOMContentLoaded",PortfolioEngine.init):PortfolioEngine.init();